[data-slot="composer-host"]{border-radius:var(--sx-r-card)!important;box-shadow:var(--sx-card)!important}
[data-slot="composer-shell"]::before{border-radius:var(--sx-r-card)!important}
[data-user-message-bubble]{border-radius:var(--sx-r-card)!important;box-shadow:var(--sx-edge)!important}
.chat-markdown-codeblock{border-radius:var(--sx-r-md)!important;box-shadow:var(--sx-edge),0 0 0 1px var(--sx-line)!important}
[data-thread-details-card]{border-radius:var(--sx-r-card)!important;box-shadow:var(--sx-card)!important}
:is([data-slot="dialog-popup"],[data-slot="alert-dialog-popup"],[data-slot="command-dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="select-popup"],[data-slot="combobox-popup"],[data-slot="autocomplete-popup"]){border-radius:var(--sx-r-card)!important;box-shadow:var(--sx-pop)!important}
[data-slot="tooltip-popup"]{border-radius:var(--sx-r-md)!important}
:root:root{--control-radius:var(--sx-r-btn)}
:is([data-slot="button"],[data-slot="select-trigger"]){border-radius:var(--sx-r-btn)!important}
[data-slot="input"]{border-radius:var(--sx-r-md)!important;transition:box-shadow var(--sx-med,220ms) ease}
[data-slot="input"]:focus-visible{box-shadow:0 0 0 3px color-mix(in srgb,var(--sx-accent) 22%,transparent)!important}
[data-sidebar-row]{border-radius:var(--sx-r-md)!important}
svg.lucide{stroke-width:1.75}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
